{
  "technical_and_design_decisions": [
    "Adopt Go modules as the standard dependency management mechanism for all externalized Fabric components, eliminating the need to copy and modify Fabric code into the SDK's internal/ and third_party/ directories.",
    "Implement thin wrapper layers for components with existing custom SDK modifications to preserve backward compatibility with the existing public SDK API, avoiding breaking changes for SDK consumers.",
    "Pin stable, compatible versions of all external Fabric dependencies in the SDK's go.mod file to prevent unexpected breaking changes from upstream component updates.",
    "Implement the temporary chaincode go.mod workaround as an isolated, clearly marked module with explicit deprecation warnings, to be removed once the full Go module transition for chaincode is complete.",
    "Remove all obsolete copied code from the SDK repository once external dependencies are verified to work correctly, to eliminate code duplication and reduce long-term maintenance burden."
  ],
  "assumptions": [
    "All required external Fabric components (gossip, cauthdsl, ccprovider, ledger, common, configtxgen, configtxlator) have publicly available, stable Go module releases compatible with the current fabric-sdk-go version, or can be forked with minimal changes to maintain compatibility.",
    "The existing fabric-sdk-go test suite provides sufficient coverage for all functionality that relies on the copied code, allowing verification that externalized dependencies work as expected without writing entirely new test cases.",
    "The temporary chaincode go.mod workaround only needs to support Go versions 1.11 to 1.16, as newer Go versions have native support for the required chaincode dependency resolution functionality, allowing the workaround to be safely deprecated after that.",
    "All external Fabric components are licensed under terms compatible with the fabric-sdk-go license, eliminating legal barriers to using them as external dependencies.",
    "Custom modifications made to the copied code in the SDK are minimal and can be either upstreamed to the corresponding Fabric components or implemented as small, maintainable wrapper layers in the SDK, requiring no major rework of existing SDK functionality."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analyze existing copied code and document modifications",
      "activity_description": "Review all copied/modified Fabric code in the SDK's internal/ and third_party/ directories, map each to corresponding external Fabric components, document all custom modifications made in the SDK, and identify compatibility requirements for external dependencies.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Configure Go module dependencies",
      "activity_description": "Add all required external Fabric component dependencies to the SDK's go.mod file, pin stable compatible versions, and verify that all dependencies resolve correctly without conflicts.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Replace gossip protoext copied code (U1)",
      "activity_description": "Remove copied gossip protoext code from the SDK, update all import paths to use the external module, and run targeted tests to verify gossip-related functionality remains intact.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Replace cauthdsl copied utilities (U2)",
      "activity_description": "Remove copied cauthdsl utilities from the SDK, update import paths to use the external module, and run targeted tests to verify cauthdsl-related functionality remains intact.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "Replace ccprovider copied structures (U3)",
      "activity_description": "Remove copied ccprovider structures from the SDK, update import paths to use the external module, and run targeted tests to verify ccprovider-related functionality remains intact.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Replace ledger copied structures (U4)",
      "activity_description": "Remove copied ledger structures from the SDK, update import paths to use the external module, and run targeted tests to verify ledger-related functionality remains intact.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "Replace common utilities copied code (U5)",
      "activity_description": "Remove copied common utility code from both internal/github.com/hyperledger/fabric/common and internal/github.com/hyperledger/fabric/core directories, update import paths to use external modules, and run targeted tests to verify common utility functionality remains intact.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement temporary chaincode go.mod workaround (U6)",
      "activity_description": "Develop isolated logic to parse and honor go.mod files included in chaincode packages, implement dependency resolution for chaincode, add explicit deprecation markers and documentation for the temporary workaround, and test the functionality with sample chaincode.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A9",
      "activity_name": "Replace configtxgen copied functions (U7)",
      "activity_description": "Remove copied configtxgen functions from the SDK, update import paths to use the external module, add thin wrapper layers to maintain backward compatibility with the existing SDK API, and run targeted tests to verify configtxgen functionality remains intact.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "Replace configtxlator copied functions (U8)",
      "activity_description": "Remove copied configtxlator functions from the SDK, update import paths to use the external module, add thin wrapper layers to maintain backward compatibility with the existing SDK API, and run targeted tests to verify configtxlator functionality remains intact.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Clean up obsolete copied code",
      "activity_description": "Delete all remaining obsolete copied code from the SDK's internal/ and third_party/ directories, remove any leftover import references to the deleted code, and run static analysis to ensure no unused code remains.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "Execute full regression testing",
      "activity_description": "Run the complete fabric-sdk-go test suite to verify all functionality is preserved after dependency replacements and cleanup, fix any issues identified during testing, and re-run tests to confirm full pass.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A13",
      "activity_name": "Update SDK documentation",
      "activity_description": "Update all relevant SDK documentation to reflect the removal of copied code, list new external dependencies, and document the temporary chaincode go.mod workaround including its deprecation timeline.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 31
  }
}

